 const [filter,setFilter]=useState<Filter>('all'),[category,setCategory]=useState('all'),[sort,setSort]=useState('menu'),[picked,setPicked]=useState<Record<string,string[]>>({}),[showSelected,setShowSelected]=useState(false),[held,setHeld]=useState<Record<string,string[]>>({}),[issues,setIssues]=useState(false),[issueKind,setIssueKind]=useState<'all'|'data'>('data'),[more,setMore]=useState(false),[metadata,setMetadata]=useState<Row|null>(null);
 const [action,setAction]=useState('off'),[bulk,setBulk]=useState<{ids:string[];action:string;revision:number}|null>(null),[componentEdit,setComponentEdit]=useState<{view:'dishes'|'house-made';ids:string[];mode:'add'|'replace'}|null>(null),[bulkValue,setBulkValue]=useState('Main Dishes'),[error,setError]=useState(''),[busy,setBusy]=useState(false),[undo,setUndo]=useState<{action:string;rows:{id:string;before:unknown;after:unknown}[]}|null>(null);
 const filterContexts=useRef(new Map<string,{filter:Filter;category:string;showSelected:boolean;sort:string}>()),detailScrolls=useRef(new Map<string,number>());
