 const recipe=menu.recipes.find(r=>r.id===selection.variantId&&r.menuId===selection.dishId)??menu.recipes.find(r=>r.menuId===selection.dishId&&r.active)??menu.recipes.find(r=>r.menuId===selection.dishId)??(!selection.dishId&&view==='dishes'?displayed[0]?.recipe:undefined);
 const rootItem=view!=='dishes'?allRows.find(row=>row.id===selection.itemId)?.item??(!selection.itemId?displayed[0]?.item:undefined):undefined;
 const item=selection.itemId?menu.items.find(item=>item.id===selection.itemId&&(view==='dishes'||graph.currentUses(item.id).length>0)):rootItem;
 const dish=menu.dishes.find(d=>d.id===recipe?.menuId),context=item?.id??recipe?.id??'empty';
 const selectedRow=allRows.find(row=>row.id===(view==='dishes'?recipe?.id:selection.itemPath?.[0]??item?.id));
 const mobileDetail=!!(selection.itemId||selection.dishId);
 const navigate=(next:MenuSelection)=>{scrolls.current.set(view,table.current?.scrollTop??0);savedContexts.current.set(view,selection);onNavigate(next);};
