 const tab=(next:MenuSelection['view'])=>{setIssues(false);setAction(next==='dishes'?'off':'specification');setBulkValue(next==='dishes'?'Main Dishes':'');filterContexts.current.set(view,{filter,category,showSelected,sort});const stored=filterContexts.current.get(next);setFilter(stored?.filter??'all');setCategory(stored?.category??'all');setSort(stored?.sort??'menu');setShowSelected(stored?.showSelected??false);navigate(savedContexts.current.get(next)??{view:next,scope:'current'});};
 useLayoutEffect(()=>{if(previousView.current!==view){if(table.current)table.current.scrollTop=scrolls.current.get(view)??0;previousView.current=view;}},[view]);
 useEffect(()=>{const key=(e:KeyboardEvent)=>{if(e.key==='/'&&!e.metaKey&&!e.ctrlKey&&!['INPUT','SELECT','TEXTAREA'].includes((e.target as HTMLElement).tagName)&&!document.querySelector('[role=dialog]')){e.preventDefault();search.current?.focus();}};window.addEventListener('keydown',key);return()=>window.removeEventListener('keydown',key);},[]);
 const mark=(ids:string[])=>setHeld(old=>({...old,[view]:[...new Set([...(old[view]??[]),...ids])]}));
