  {error&&<div className="mc-alert" role="alert">{error}</div>}
  {bulkForm.value.pending&&<div className="mc-notice" role="status">A house-made bulk save needs its original receipt. <button disabled={busy} onClick={()=>{const pending=bulkForm.value.pending!;navigate({view:pending.view,scope:'current'});setBulk({ids:pending.command.itemIds,action:'reopen',revision:pending.revision});}}>Retry original bulk save</button><button onClick={bulkForm.download}>Download request</button></div>}
